import{_ as e,o as t,c as s,ag as o}from"./chunks/framework.CrXGS008.js";const k=JSON.parse('{"title":"API HTTP","description":"","frontmatter":{},"headers":[],"relativePath":"pt/nay-lib/api.md","filePath":"pt/nay-lib/api.md"}'),i={name:"pt/nay-lib/api.md"};function d(n,a,r,p,l,c){return t(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="api-http" tabindex="-1">API HTTP <a class="header-anchor" href="#api-http" aria-label="Permalink to &quot;API HTTP&quot;">​</a></h1><p>Scripts e sites (painéis, bots do Discord, lojas) podem ler e alterar o servidor através de uma API JSON servida pelo FXServer na porta do jogo:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;server ip&gt;:&lt;port&gt;/&lt;resource&gt;/v1/&lt;route&gt;</span></span></code></pre></div><h2 id="ativar-a-api" tabindex="-1">Ativar a API <a class="header-anchor" href="#ativar-a-api" aria-label="Permalink to &quot;Ativar a API&quot;">​</a></h2><p>A API vem <strong>desativada por predefinição</strong>. Ative-a no <code>/nay</code>, na página <strong>Nayretis</strong>: <strong>API HTTP</strong> (<code>ApiEnabled</code>). Enquanto estiver desativada, todas as rotas respondem <code>503 api_disabled</code>. <strong>Tamanho máximo do pedido (KB)</strong> (<code>ApiMaxBodyKb</code>) limita o corpo dos pedidos (1024 KB por predefinição).</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><p>Crie tokens no separador <strong>API</strong> do <code>/nay</code> (o token só é mostrado uma vez: copie-o nesse momento) ou a partir da consola do servidor:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_api_token create &lt;label&gt; &lt;scope...&gt;</span></span>
<span class="line"><span>nay_api_token list</span></span>
<span class="line"><span>nay_api_token revoke &lt;id&gt;</span></span></code></pre></div><p>Um token tem o formato <code>nay_&lt;id&gt;_&lt;secret&gt;</code>. Só é guardado o respetivo hash SHA-256. Cada token tem os seus âmbitos, endereços permitidos opcionais (IPv4, IPv6 ou intervalos CIDR), um limite de pedidos por minuto e uma expiração opcional.</p><p>Os âmbitos têm o formato <code>&lt;resource&gt;.&lt;scope&gt;</code>, com caracteres universais: <code>nay_car_wash.*</code> dá acesso a todas as rotas de um script, <code>*</code> dá acesso a tudo. Cada script lista as suas rotas e âmbitos na respetiva página, por exemplo <a href="/pt/car-wash/api">Car Wash</a>.</p><h2 id="pedidos" tabindex="-1">Pedidos <a class="header-anchor" href="#pedidos" aria-label="Permalink to &quot;Pedidos&quot;">​</a></h2><ul><li>Envie <code>Authorization: Bearer &lt;token&gt;</code>.</li><li>Os corpos são JSON (<code>Content-Type: application/json</code>) com um <code>Content-Length</code>. Os corpos em chunks são recusados.</li><li>Depois de 10 autenticações falhadas num minuto, os pedidos sem token válido vindos desse endereço são recusados durante 5 minutos. Os tokens válidos continuam a funcionar.</li><li>Atrás de um proxy inverso, defina <code>nay:apiTrustedProxies</code> (consulte <a href="#https">HTTPS</a>). Caso contrário, todos os clientes partilham o endereço do proxy.</li></ul><p>Cada resposta é JSON com um cabeçalho <code>X-Request-Id</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;forbidden&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;This token does not allow this route&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { } } }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Status</th><th>Código</th><th>Significado</th></tr></thead><tbody><tr><td>400</td><td><code>unexpected_body</code>, <code>invalid_json</code>, <code>invalid_request</code></td><td>Corpo enviado a uma rota sem corpo, corpo que não é JSON válido, ou <code>Content-Length</code> mal formado.</td></tr><tr><td>401</td><td><code>unauthorized</code></td><td>Token em falta, desconhecido, revogado ou expirado.</td></tr><tr><td>403</td><td><code>forbidden</code>, <code>ip_not_allowed</code></td><td>O token não tem o âmbito, ou o endereço não é permitido para ele.</td></tr><tr><td>404 / 405</td><td><code>not_found</code>, <code>method_not_allowed</code></td><td>Rota desconhecida, ou método errado numa rota conhecida.</td></tr><tr><td>411</td><td><code>length_required</code></td><td>Qualquer <code>Transfer-Encoding</code> (corpo em chunks).</td></tr><tr><td>413</td><td><code>payload_too_large</code></td><td>Corpo acima de <code>ApiMaxBodyKb</code>. Um <code>Content-Length</code> anunciado acima de 10 MB é recusado antes de o corpo ser lido.</td></tr><tr><td>415</td><td><code>unsupported_media_type</code></td><td>Corpo que não é <code>application/json</code>.</td></tr><tr><td>422</td><td><code>invalid_request</code>, <code>unknown_parameter</code>, <code>invalid_value</code></td><td>Parâmetro, query ou corpo que não passa na validação (<code>details.path</code> e <code>details.reason</code>).</td></tr><tr><td>429</td><td><code>rate_limited</code>, <code>too_many_failures</code></td><td>Token acima do limite por minuto, ou endereço bloqueado. Consulte <code>Retry-After</code>.</td></tr><tr><td>500</td><td><code>internal_error</code></td><td>A rota falhou. Consulte a consola do servidor.</td></tr><tr><td>503</td><td><code>api_disabled</code>, <code>not_ready</code></td><td>API desativada, ou recurso ainda a arrancar (<code>Retry-After</code>).</td></tr><tr><td>504</td><td><code>timeout</code></td><td>A rota não respondeu em 10 segundos. Continua a ser executada: uma alteração pode ainda ser aplicada depois do 504, por isso leia o estado de novo antes de tentar outra vez.</td></tr></tbody></table><h2 id="rotas-do-nay-lib" tabindex="-1">Rotas do nay_lib <a class="header-anchor" href="#rotas-do-nay-lib" aria-label="Permalink to &quot;Rotas do nay_lib&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Rota</th><th>Âmbito</th><th>Dados</th></tr></thead><tbody><tr><td>GET</td><td><code>/nay_lib/v1/status</code></td><td><code>nay.status</code></td><td>Nome do servidor, jogadores, máximo de jogadores, framework, inventário, target, recursos Nayretis e versões.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/players</code></td><td><code>nay.players</code></td><td>Jogadores ligados: id, nome, personagem, identificador, profissão.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/settings/:resource</code></td><td><code>nay.settings</code> mais <code>&lt;resource&gt;.config</code> ou <code>nay.config</code></td><td>Definições de um script com os respetivos valores.</td></tr><tr><td>PUT</td><td><code>/nay_lib/v1/settings/:resource/:key</code></td><td>o mesmo</td><td>Altera uma definição. Corpo <code>{ &quot;value&quot;: ... }</code>.</td></tr><tr><td>DELETE</td><td><code>/nay_lib/v1/settings/:resource/:key</code></td><td>o mesmo</td><td>Repõe uma definição no valor predefinido.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/audit</code></td><td><code>nay.audit</code></td><td>Registo, 50 linhas por página. Query <code>resource</code>, <code>action</code>, <code>actor</code>, <code>from</code> e <code>to</code> (segundos Unix), <code>page</code>.</td></tr></tbody></table><p>Cada chamada que altera algo fica gravada no <a href="/pt/nay-lib/audit">registo</a> (<code>api.call</code>, autor <code>api:&lt;token label&gt;</code>).</p><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>O FXServer só fala HTTP simples: qualquer pessoa no caminho pode ler um token enviado por ele. Coloque um proxy inverso com certificado à frente da API e exponha apenas as rotas que usa. Depois indique ao <code>nay_lib</code> em que proxies confiar, para que os endereços permitidos e os limites de pedidos se apliquem ao endereço real do cliente, obtido a partir de <code>X-Forwarded-For</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set nay:apiTrustedProxies &quot;127.0.0.1&quot;</span></span></code></pre></div><p>O valor é uma lista de endereços ou intervalos CIDR separados por vírgulas.</p><p>nginx:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api.example.com;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	ssl_certificate </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/letsencrypt/live/api.example.com/fullchain.pem;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	ssl_certificate_key </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/letsencrypt/live/api.example.com/privkey.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	location</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ~</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;"> ^/(nay_lib|nay_car_wash)/v1/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:30120;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		client_max_body_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1m</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Caddy (certificado obtido automaticamente):</p><div class="language-caddy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">caddy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.example.com {</span></span>
<span class="line"><span>	@nayretis path_regexp ^/(nay_lib|nay_car_wash)/v1/</span></span>
<span class="line"><span>	reverse_proxy @nayretis 127.0.0.1:30120</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,26)])])}const u=e(i,[["render",d]]);export{k as __pageData,u as default};
